function art(m,wide=false){const w=wide?1440:400,h=wide?650:600;let scene='';const col=m.color;if(m.theme==='city'){for(let i=0;i<34;i++){let x=i*w/30-30,bh=60+((i*47)%210)*(wide?1:1.15);scene+=`<rect x="${x}" y="${h*.83-bh}" width="${w/30-3}" height="${bh+180}" fill="${i%3?'#0B0D12':'#161A22'}"/>`;for(let j=0;j<5;j++)scene+=`<rect x="${x+9}" y="${h*.83-bh+18+j*26}" width="3" height="8" fill="${col}" opacity="${j%2?.6:.2}"/>`;}scene+=`<path d="M${w*.47} ${h}L${w*.57} ${h*.65}L${w*.61} ${h*.65}L${w*.73} ${h}" fill="#F5C51831"/><path d="M${w*.6} ${h}L${w*.59} ${h*.67}" stroke="#F5C518" opacity=".55"/>`;}else if(m.theme==='planet'){scene=`<circle cx="${w*.6}" cy="${h*.34}" r="${wide?165:112}" fill="url(#planet)"/><ellipse cx="${w*.6}" cy="${h*.34}" rx="${wide?270:170}" ry="25" fill="none" stroke="#A8B0BC" stroke-width="2" opacity=".5" transform="rotate(-25 ${w*.6} ${h*.34})"/><path d="M0 ${h*.79} Q${w*.3} ${h*.54} ${w*.52} ${h*.77}T${w} ${h*.72}V${h}H0Z" fill="#0B0D12"/>`;}else if(m.theme==='door'){scene=`<rect x="${w*.24}" y="${h*.15}" width="${w*.52}" height="${h*.64}" fill="#0B0D12" stroke="#303846" stroke-width="7"/><path d="M${w*.31} ${h*.19}L${w*.6} ${h*.25}V${h*.77}L${w*.31} ${h*.81}Z" fill="#0B0D12"/><path d="M${w*.63} ${h*.23}v${h*.53}" stroke="#F4F5F7" stroke-width="4"/><text x="${w*.43}" y="${h*.36}" fill="#E31C23" font-size="32">9</text><path d="M${w*.63} ${h*.76}L${w*.1} ${h}H${w}Z" fill="#F4F5F715"/>`;}else{scene=`<path d="M0 ${h*.5}L${w*.2} ${h*.24}L${w*.45} ${h*.5}L${w*.7} ${h*.3}L${w} ${h*.55}V${h}H0Z" fill="#161A22"/><path d="M0 ${h*.66}L${w*.3} ${h*.45}L${w*.53} ${h*.69}L${w*.8} ${h*.48}L${w} ${h*.68}V${h}H0Z" fill="#0B0D12"/><path d="M0 ${h*.8}Q${w*.4} ${h*.68} ${w} ${h*.85}V${h}H0Z" fill="#0B0D12"/><path d="M${w*.51} ${h*.63}Q${w*.3} ${h*.78} ${w*.55} ${h*.86}T${w*.25} ${h}" fill="none" stroke="${col}" stroke-width="${wide?40:16}" opacity=".45"/>`;}
let stars='';for(let i=0;i<65;i++)stars+=`<circle cx="${(i*137+23)%w}" cy="${(i*71+5)%(h*.65)}" r="${i%3?.65:1.1}" fill="#F4F5F7" opacity="${i%2?.3:.6}"/>`;
return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}"><defs><linearGradient id="sky" x2=".4" y2="1"><stop stop-color="#0B0D12"/><stop offset=".5" stop-color="${col}"/><stop offset="1" stop-color="#0B0D12"/></linearGradient><radialGradient id="sun"><stop stop-color="#F4F5F7"/><stop offset=".4" stop-color="${col}" stop-opacity=".8"/><stop offset="1" stop-color="${col}" stop-opacity="0"/></radialGradient><linearGradient id="shade" x2="0" y2="1"><stop offset=".3" stop-color="#0B0D12" stop-opacity="0"/><stop offset="1" stop-color="#0B0D12"/></linearGradient><radialGradient id="planet" cx=".25" cy=".2"><stop stop-color="#F4F5F7"/><stop offset=".4" stop-color="${col}"/><stop offset="1" stop-color="#161A22"/></radialGradient><filter id="noise"><feTurbulence type="fractalNoise" baseFrequency=".65" numOctaves="3" stitchTiles="stitch"/><feColorMatrix type="saturate" values="0"/></filter></defs><rect width="${w}" height="${h}" fill="url(#sky)"/><circle cx="${w*.62}" cy="${h*.4}" r="${wide?330:210}" fill="url(#sun)"/>${stars}${m.theme==='city'?`<circle cx="${w*.62}" cy="${h*.4}" r="${wide?78:52}" fill="#F4F5F7" opacity=".75"/>`:''}${scene}<ellipse cx="${w*.6}" cy="${h*.88}" rx="${wide?14:6}" ry="${wide?30:18}" fill="#0B0D12"/><rect width="${w}" height="${h}" fill="url(#shade)"/><rect width="${w}" height="${h}" filter="url(#noise)" opacity=".055"/>${!wide?`<text x="200" y="48" text-anchor="middle" font-family="Arial" font-size="10" letter-spacing="5" fill="#F4F5F7">N O I R  ORIGINAL</text><text x="200" y="504" text-anchor="middle" font-family="Arial" font-size="${m.title.length>19?24:28}" font-weight="bold" fill="#F4F5F7">${esc(m.title.toUpperCase())}</text><text x="200" y="533" text-anchor="middle" font-family="Arial" font-size="9" letter-spacing="3" fill="#A8B0BC">${m.sub}</text><text x="200" y="566" text-anchor="middle" font-family="Arial" font-size="8" letter-spacing="2" fill="#A8B0BC">${m.year} • A CINEMATIC JOURNEY</text>`:''}</svg>`);}
