let S={mode:'user',page:'home',state:'ready',genre:'Tất cả',movie:1,listed:new Set(),search:'',filter:'Tất cả',query:'',selected:new Set(),isPlaying:false,progress:34,source:'Hồ Chí Minh',sourceError:false,quality:'1080p',speed:'1×',subtitle:'Tiếng Việt',muted:false,userComments:[],tick:0};let lastFocus=null;let dragId=null;const findMovie=id=>movies.find(m=>m.id===Number(id))||movies[0];const num=n=>Number(n).toLocaleString('vi-VN');
const badge=(text,color)=>`<span class="badge ${color||({'Công khai':'green','Hoạt động':'green','Healthy':'green','Đã duyệt':'green','Sẵn sàng':'green','Nháp':'amber','Chờ duyệt':'amber','Maintenance':'amber','Draining':'amber','Đang encode':'gold','Down':'red','Đã khoá':'red','Bị báo cáo':'red','Thất bại':'red'}[text]||'')}"><i class="dot"></i>${esc(text)}</span>`;
const btn=(label,action='',variant='',icon='',extra='')=>`<button class="btn ${variant}" ${action?`data-action="${action}"`:''} ${extra}>${icon?ic(icon):''}${label}</button>`;
const iconBtn=(icon,label,action,extra='')=>`<button class="icon-btn" aria-label="${esc(label)}" title="${esc(label)}" data-action="${action}" ${extra}>${ic(icon)}</button>`;
const searchInput=(placeholder,id,value='')=>`<div class="search">${ic('search')}<input id="${id}" type="search" aria-label="${esc(placeholder)}" placeholder="${esc(placeholder)}" value="${esc(value)}"></div>`;
const logo=()=>`<a href="#" class="logo" data-action="home" aria-label="VKU Cinema — trang chủ"><svg class="vku-symbol" viewBox="0 0 42 38" aria-hidden="true"><path d="M2 4h10l9 25-6 8Z" fill="#E31C23"/><path d="M18 4h10l-9 26-5-14Z" fill="#F5C518"/><path d="M30 4h10L27 37H17Z" fill="#0057B8"/></svg><span class="word"><b>VKU<span> CINEMA</span></b><small>YOUR NEXT STORY</small></span></a>`;
const demoBar=()=>`<div class="demo-bar"><div class="flex"><span class="eyebrow" style="letter-spacing:1.4px">UI / 01</span><div class="mode-switch" aria-label="Chuyển giao diện">${[['user','User'],['admin','Admin'],['server','Server'],['kit','UI kit']].map(([id,label])=>`<button data-action="mode" data-id="${id}" class="${S.mode===id?'active':''}" aria-pressed="${S.mode===id}">${label}</button>`).join('')}</div></div><div class="demo-meta"><span>Prototype tương tác · Dữ liệu mẫu</span><label><span>Trạng thái</span><select id="state-picker" aria-label="Xem trạng thái giao diện">${[['ready','Mặc định'],['loading','Loading'],['empty','Empty'],['error','Error'],['denied','Không có quyền']].map(([v,t])=>`<option value="${v}" ${S.state===v?'selected':''}>${t}</option>`).join('')}</select></label></div></div>`;
function userHeader(){return `<header class="user-head">${logo()}<div class="search-wrap">${searchInput('Tìm phim, thể loại…','user-search')}<div id="suggestions"></div></div><div class="header-actions">${iconBtn('bell','Thông báo','notifications')}<button class="avatar" data-action="user-profile" aria-label="Tài khoản Minh Anh">MA</button>${iconBtn('menu','Mở menu','user-menu').replace('class="icon-btn"','class="icon-btn menu-toggle"').replace('data-action="user-menu"','data-action="user-menu" aria-expanded="false" aria-controls="user-nav"')}</div><nav id="user-nav" aria-label="Điều hướng người xem"><a href="#" data-action="home" class="${S.page==='home'?'active':''}">Khám phá</a><a href="#" data-action="catalog" class="${S.page==='catalog'?'active':''}">Phim & series</a><a href="#" data-action="mylist" class="${S.page==='mylist'?'active':''}">Danh sách của tôi</a></nav></header>`;}
const poster=m=>`<button class="poster" data-action="detail" data-id="${m.id}" aria-label="Xem chi tiết ${esc(m.title)}"><img src="${m.poster}" alt="Poster ${esc(m.title)}" loading="lazy"><div class="poster-overlay"><span class="play-circle">${ic('play')}</span><h3>${esc(m.title)}</h3><small>★ ${m.rating} &nbsp; ${m.year} · ${m.genre}</small></div></button>`;
function home(){const m=movies[0];return `<section class="hero"><img src="${m.wide}" alt="Thành phố tương lai dưới ánh bình minh"><div class="hero-content"><div class="flex"><span class="eyebrow">VKU CINEMA ORIGINAL</span>${badge('Đang chiếu','red')}</div><h1>Phía sau<br><em>bình minh.</em></h1><div class="hero-meta"><span class="rating">★ 8.6</span><span>2026</span><span>128 phút</span><span class="badge">4K</span><span class="badge">T16</span></div><p class="desc">Khi thành phố thức giấc lần cuối, một người đưa tin phải tìm lại tín hiệu đã mất — và câu trả lời cho ngày mai.</p><div class="flex">${btn('Xem ngay','play','primary','play','data-id="1"')}${btn(S.listed.has(1)?'Đã thêm':'Thêm danh sách','list-toggle','ghost',S.listed.has(1)?'check':'plus','data-id="1"')}</div></div><div class="hero-pagination"><span>BỘ SƯU TẬP 2026</span><i></i></div></section><section class="user-section"><div class="section-head"><h2>Tiếp tục xem</h2><span class="muted" style="font-size:11px">Câu chuyện của anh, tiếp nối hôm nay</span></div><div class="row-scroll">${[movies[4],movies[1],movies[5]].map((m,i)=>`<article class="continue-card"><button class="continue-image" data-action="play" data-id="${m.id}" aria-label="Tiếp tục xem ${m.title}"><img src="${m.wide}" alt="${m.title}"><span class="play-circle">${ic('play')}</span><div class="progress"><span style="width:${[64,32,81][i]}%"></span></div></button><div class="continue-caption"><div><strong>${m.title}</strong><br><small>${i===1?'Phim lẻ':'Mùa 1 · Tập '+[3,1,8][i]}</small></div><small>Còn ${[18,72,6][i]} phút</small></div></article>`).join('')}</div></section><section class="user-section"><div class="section-head"><h2>Chọn thế giới của anh</h2>${btn('Xem tất cả','catalog','ghost sm','chevron')}</div><div class="chips">${['Tất cả','Đề xuất','Phim Việt','Hành động','Kinh dị','Anime','Viễn tưởng'].map(g=>`<button class="chip ${S.genre===g?'active':''}" data-action="genre" data-id="${g}">${g}</button>`).join('')}</div><div class="row-scroll" id="genre-row">${movies.filter(m=>m.status==='Công khai'&&(['Tất cả','Đề xuất'].includes(S.genre)||m.genre===S.genre)).map(poster).join('')}</div></section><section class="user-section"><div class="section-head"><h2>Những câu chuyện Việt</h2><small>Gần gũi. Đầy cảm xúc.</small></div><div class="row-scroll">${movies.filter(m=>m.genre==='Phim Việt'&&m.status==='Công khai').map(poster).join('')}<div class="panel panel-body" style="min-width:300px;max-width:420px;display:flex;flex-direction:column;justify-content:center"><span class="eyebrow">GÓC ĐIỆN ẢNH</span><h2 style="margin:16px 0">Một góc nhìn.<br>Nhiều điều để nhớ.</h2><p class="muted" style="font-size:12px">Khám phá những câu chuyện được kể từ chính nơi chúng ta lớn lên.</p></div></div></section>`;}
function catalog(){const listed=S.page==='mylist';const items=movies.filter(m=>m.status==='Công khai'&&(!listed||S.listed.has(m.id))&&(S.genre==='Tất cả'||S.genre==='Đề xuất'||m.genre===S.genre));return `<div class="detail"><div class="page-title"><div><span class="eyebrow">BỘ SƯU TẬP CỦA VKU CINEMA</span><h1 style="margin-top:12px">${listed?'Danh sách của tôi':'Phim & series'}</h1><p>${listed?'Những câu chuyện anh muốn xem sau.':'Tìm câu chuyện phù hợp với tâm trạng hôm nay.'}</p></div></div><div class="chips">${['Tất cả','Phim Việt','Hành động','Kinh dị','Anime','Viễn tưởng'].map(g=>`<button class="chip ${S.genre===g?'active':''}" data-action="genre" data-id="${g}">${g}</button>`).join('')}</div>${items.length?`<div class="responsive-grid">${items.map(poster).join('')}</div>`:empty('Danh sách còn trống','Thêm phim bằng nút “Thêm danh sách” ở trang chi tiết.','Khám phá phim','home')}</div>`;}
function detail(){const m=findMovie(S.movie);return `<div class="detail">${btn('Quay lại khám phá','home','ghost sm','back')}<div class="detail-top"><img class="detail-poster" src="${m.poster}" alt="${m.title}"><div><span class="eyebrow">VKU CINEMA ORIGINAL · ${m.genre}</span><h1>${m.title}</h1><p class="muted" style="font-size:13px">${m.sub}</p><div class="hero-meta" style="margin-top:20px"><span class="rating">★ ${m.rating}</span><span>${m.year}</span><span>${m.duration}</span>${badge('4K','gold')}${badge('T16')}</div><p class="description">${m.id===1?'Khi thành phố thức giấc lần cuối, một người đưa tin phải tìm lại tín hiệu đã mất. Hành trình qua những ký ức bỏ quên đưa anh đến lựa chọn giữa một thế giới an toàn và sự thật về ngày mai.':'Một hành trình khám phá những điều còn chưa được nói ra. Giữa những ngã rẽ, các nhân vật tìm thấy sức mạnh để bắt đầu lại và kết nối với những người họ yêu thương.'}</p><div class="flex wrap">${btn('Xem ngay','play','primary','play',`data-id="${m.id}"`)}${btn(S.listed.has(m.id)?'Đã thêm danh sách':'Thêm danh sách','list-toggle','ghost',S.listed.has(m.id)?'check':'plus',`data-id="${m.id}"`)}</div><p class="muted" style="font-size:11px;margin-top:22px">Âm thanh gốc · Phụ đề Tiếng Việt / English · Nội dung minh hoạ</p></div></div><div class="detail-sections"><div class="stack"><section class="panel"><div class="panel-head"><h3>${m.duration.includes('tập')?'Danh sách tập':'Phiên bản phát'}</h3>${m.duration.includes('tập')?'<select aria-label="Chọn mùa"><option>Mùa 1</option></select>':badge('Phim lẻ')}</div><div class="panel-body"><div class="episode-grid">${Array.from({length:m.duration.includes('tập')?parseInt(m.duration):1},(_,i)=>btn(m.duration.includes('tập')?'Tập '+(i+1):'Bản đầy đủ','episode-play','ghost','',`data-id="${m.id}" data-episode="${i+1}"`)).join('')}</div></div></section><section class="panel"><div class="panel-head"><h3>Bình luận <span class="muted">(${2+S.userComments.filter(c=>c.movie===m.id).length})</span></h3><small>Giữ trải nghiệm xem văn minh</small></div><div class="panel-body"><form id="comment-form"><label class="field">Chia sẻ cảm nhận của anh<textarea name="comment" required maxlength="500" placeholder="Anh nghĩ sao về bộ phim này?"></textarea></label><div style="margin-top:12px;text-align:right"><button class="btn primary" type="submit">Gửi bình luận</button></div></form>${[...S.userComments.filter(c=>c.movie===m.id),{name:'Minh Anh',text:'Phần hình ảnh và âm thanh rất có cảm xúc.'},{name:'Hải Nguyễn',text:'Một câu chuyện đáng để xem chậm lại.'}].map(c=>`<div class="comment"><span class="avatar">${esc(c.name.slice(0,2).toUpperCase())}</span><div><strong style="font-size:12px">${esc(c.name)}</strong> <small>· ${c.pending?'Chờ duyệt':'Hôm nay'}</small><p>${esc(c.text)}</p></div></div>`).join('')}</div></section></div><section><h2 style="margin-bottom:18px">Có thể anh sẽ thích</h2><div class="row-scroll">${movies.filter(x=>x.status==='Công khai'&&x.id!==m.id).slice(0,2).map(poster).join('')}</div></section></div></div>`;}
function player(){const m=findMovie(S.movie);return `<div class="player-shell"><div class="section-head">${btn('Chi tiết phim','detail','ghost sm','back',`data-id="${m.id}"`)}${badge('Preview · không có nội dung phim','gold')}</div><div class="player" id="player-container"><img src="${m.wide}" alt="Khung hình minh hoạ ${m.title}"><div class="player-screen">${S.sourceError?`${ic('alert')}<h2>Nguồn phát không phản hồi</h2><p>Điểm phát Hồ Chí Minh tạm thời gián đoạn. Có thể chuyển sang Singapore.</p>${btn('Chuyển sang nguồn dự phòng','fallback','primary','refresh')}`:`${btn(S.isPlaying?ic('pause'):ic('play'),'toggle-play','primary','',`aria-label="${S.isPlaying?'Tạm dừng':'Phát thử'}"`)}<p>${S.isPlaying?'Đang mô phỏng tiến trình phát':'Bấm phát để thử giao diện player'}</p>`}</div><div class="player-controls"><input type="range" id="seek" aria-label="Tiến trình phát thử" min="0" max="100" value="${S.progress}"><div class="flex between"><div class="flex">${iconBtn(S.isPlaying?'pause':'play',S.isPlaying?'Tạm dừng':'Phát','toggle-play')}${iconBtn('volume',S.muted?'Bật âm thanh':'Tắt âm thanh','mute')}<span id="play-time">${Math.floor(S.progress*1.28)}:00 / 128:00</span><span>${S.muted?'Tắt tiếng':''}</span></div><div class="flex"><span>${S.quality}</span>${iconBtn('expand','Toàn màn hình','fullscreen')}</div></div></div></div><div class="player-settings">${[['Nguồn phát','player-source',['Hồ Chí Minh','Singapore','Hà Nội'],S.source],['Chất lượng','player-quality',['Tự động','1080p','720p','360p'],S.quality],['Phụ đề','player-subtitle',['Tiếng Việt','English','Tắt'],S.subtitle],['Tốc độ','player-speed',['0.75×','1×','1.25×','1.5×','2×'],S.speed]].map(([label,id,opts,val])=>`<label>${label}<select id="${id}">${opts.map(o=>`<option ${o===val?'selected':''}>${o}</option>`).join('')}</select></label>`).join('')}<div class="grow"></div>${btn('Thử lỗi nguồn','simulate-source','ghost sm','alert')}</div><div class="divider"></div><h2>${m.title}${S.episode?' · Tập '+S.episode:''}</h2><p class="muted" style="margin-top:8px;font-size:12px">Player prototype: các điều khiển thay đổi trạng thái mô phỏng. Chưa kết nối video, phụ đề hoặc CDN thật.</p></div>`;}
const adminNav=[['dashboard','Dashboard','grid'],['movies','Phim','film'],['episodes','Tập / Season','layers'],['genres','Thể loại','tag'],['users','Người dùng','users'],['comments','Bình luận','comment'],['banners','Banner / Hero','image'],['sources','Máy chủ phát','server'],['reports','Báo cáo','chart'],['settings','Cài đặt','settings']];
const serverNav=[['overview','Tổng quan cụm','activity'],['nodes','Node / Server','server'],['transcode','Nguồn & Transcode','cpu'],['routing','Routing / Failover','route'],['logs','Log & Cảnh báo','log'],['storage','Lưu trữ & CDN','layers'],['settings','Cài đặt vận hành','settings']];
const kitNav=[['tokens','Design tokens','grid'],['components','Components','layers'],['states','Trạng thái UX','shield'],['handoff','Bàn giao dev','log']];
function sidebar(){const nav=S.mode==='admin'?adminNav:S.mode==='server'?serverNav:kitNav;return `<aside class="sidebar" id="sidebar">${logo()}<div class="workspace">${ic(S.mode==='server'?'server':S.mode==='kit'?'layers':'shield')}<div><strong style="font-size:12px">${S.mode==='admin'?'Content Studio':S.mode==='server'?'Operations':'Design System'}</strong><small>${S.mode==='server'?'VKU CINEMA · Cụm Đông Nam Á':'VKU CINEMA · Workspace'}</small></div></div><div class="nav-label">${S.mode==='server'?'HẠ TẦNG PHÁT SÓNG':'KHÔNG GIAN LÀM VIỆC'}</div><nav>${nav.map(([id,label,icon])=>`<button class="nav-item ${S.page===id?'active':''}" data-action="page" data-id="${id}" title="${label}" ${S.page===id?'aria-current="page"':''}>${ic(icon)}<span>${label}</span>${id==='comments'?'<span class="count">2</span>':id==='logs'?'<span class="count">3</span>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="flex"><span class="avatar">${S.mode==='server'?'OP':'BB'}</span><div><strong style="color:var(--text);font-size:11px">${S.mode==='server'?'Operations team':'Thái Bá Bằng'}</strong><br><small>${S.mode==='server'?'Infrastructure admin':'Workspace admin'}</small></div></div><p style="margin-top:18px;font-size:10px">${S.mode==='server'?'<span class="positive">●</span> Mô phỏng realtime · 5 giây':'Design system v2.0 · Sep 2026'}</p></div></aside>`;}
function topbar(){const nav=S.mode==='admin'?adminNav:S.mode==='server'?serverNav:kitNav;return `<header class="topbar">${iconBtn('menu','Mở điều hướng','sidebar-menu').replace('class="icon-btn"','class="icon-btn mobile-menu"')}<div class="breadcrumb">${S.mode==='admin'?'Studio':S.mode==='server'?'Operations':'Design'} <span style="margin:0 10px">/</span> <b>${nav.find(n=>n[0]===S.page)?.[1]||''}</b></div>${searchInput('Tìm phim, người dùng, node…','global-search')}<div class="flex">${iconBtn('bell','Thông báo hệ thống','notifications')}<span class="avatar">${S.mode==='server'?'OP':'BB'}</span></div></header>`;}
const pageTitle=(title,desc,actions='')=>`<div class="page-title"><div><h1>${title}</h1><p>${desc}</p></div><div class="flex wrap">${actions}</div></div>`;
const kpi=(title,value,foot,icon,trend='')=>`<div class="panel kpi"><div class="kpi-title">${title}${ic(icon)}</div><div class="kpi-value">${value}</div><div class="kpi-foot">${trend?`<span class="positive">↗ ${trend}</span> &nbsp;`:''}${foot}</div></div>`;
function chart(kind='views'){return `<svg class="chart" viewBox="0 0 660 205" role="img" aria-label="${kind==='views'?'Lượt xem mẫu tăng từ 18 nghìn đến 28 nghìn trong 7 ngày':'Băng thông mẫu dao động từ 2 đến 4 Gbps'}"><defs><linearGradient id="area-${kind}" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#F5C518" stop-opacity=".20"/><stop offset="1" stop-color="#F5C518" stop-opacity="0"/></linearGradient></defs>${[25,75,125,175].map((y,i)=>`<line class="chart-grid" x1="40" x2="645" y1="${y}" y2="${y}"/><text x="0" y="${y+3}">${kind==='views'?['30k','20k','10k','0'][i]:['6 G','4 G','2 G','0'][i]}</text>`).join('')}<path d="M42 134C75 134 106 91 140 96S208 132 240 108S302 56 340 69S406 100 440 82S506 32 540 43S611 25 640 29V175H42Z" fill="url(#area-${kind})"/><path class="chart-line" d="M42 134C75 134 106 91 140 96S208 132 240 108S302 56 340 69S406 100 440 82S506 32 540 43S611 25 640 29"/><circle cx="640" cy="29" r="4" fill="#F5C518"/></svg><div class="chart-labels">${(kind==='views'?['09/09','10/09','11/09','12/09','13/09','14/09','15/09']:['14:00','14:10','14:20','14:30','14:40','14:50','15:00']).map(t=>`<span>${t}</span>`).join('')}</div>`;}
function dashboard(){return `${pageTitle('Tổng quan nội dung','Thứ Ba, 15 tháng 9 · Một ngày mới, những câu chuyện mới.',btn('Xuất báo cáo','export','ghost','download')+btn('Thêm phim','new-movie','primary','plus'))}<div class="stack"><div class="kpis">${kpi('Lượt xem hôm nay','28.406','so với hôm qua','eye','12,8%')}${kpi('Người dùng online','1.284','phiên hoạt động hiện tại','users','8,2%')}${kpi('Phim mới trong tuần','12','8 công khai · 4 bản nháp','film')}${kpi('Tỷ lệ lỗi phát','0,42%','<span class="positive">↓ 0,18%</span> so với hôm qua','activity')}</div><div class="charts"><section class="panel"><div class="panel-head"><div><h3>Lượt xem 7 ngày</h3><small>Tổng 164.820 lượt xem</small></div><span class="legend">Lượt xem</span></div><div class="panel-body">${chart()}</div></section><section class="panel"><div class="panel-head"><h3>Đang được xem nhiều</h3>${ic('chart')}</div><div class="panel-body" style="padding-top:6px;padding-bottom:6px">${movies.slice(0,4).map((m,i)=>`<div class="top-film"><span class="rank">0${i+1}</span><img src="${m.poster}" alt=""><div><strong>${m.title}</strong><small>${m.genre}</small></div><span class="views">${num(m.views)}</span></div>`).join('')}</div></section></div><section class="panel"><div class="panel-head"><div><h3>Cần chú ý</h3><small>Bản quyền sắp hết hạn và nội dung bị báo cáo</small></div>${badge('3 nội dung','amber')}</div><div class="table-scroll"><table><thead><tr><th>NỘI DUNG</th><th>VẤN ĐỀ</th><th>THỜI HẠN / SỐ LƯỢNG</th><th>PHỤ TRÁCH</th><th></th></tr></thead><tbody>${[movies[3],movies[7],movies[0]].map((m,i)=>`<tr><td>${movieCell(m)}</td><td>${badge(i===2?'Bị báo cáo':'Sắp hết bản quyền',i===2?'red':'amber')}</td><td>${i===2?'12 báo cáo nguồn phát':m.expires}</td><td><span class="avatar" style="width:25px;height:25px;margin-right:6px">BB</span> Nội dung</td><td>${btn('Xem chi tiết',i===2?'report-detail':'edit-movie','ghost sm','chevron',`data-id="${m.id}"`)}</td></tr>`).join('')}</tbody></table></div></section></div>`;}
const movieCell=m=>`<div class="movie-cell"><img src="${m.poster}" alt=""><div><strong>${esc(m.title)}</strong><small>${m.genre} · ${m.duration}</small></div></div>`;
const tableWrap=(heads,rows,footer='')=>`<div class="table-scroll"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table></div>${footer?`<div class="table-footer">${footer}</div>`:''}`;
function filterbar(statuses=['Tất cả','Công khai','Nháp','Ẩn'],placeholder='Tìm tên phim hoặc năm…'){return `<div class="toolbar">${searchInput(placeholder,'table-query',S.query)}<select id="table-filter" aria-label="Lọc trạng thái">${statuses.map(v=>`<option ${S.filter===v?'selected':''}>${v}</option>`).join('')}</select><div class="grow"></div>${btn('Bỏ lọc','clear-filter','ghost sm','refresh')}</div>`;}
function matches(text,status){return (S.filter==='Tất cả'||status===S.filter)&&text.toLowerCase().includes(S.query.toLowerCase());}
function movieRows(){const items=movies.filter(m=>matches(m.title+' '+m.year,m.status));return items.length?tableWrap(['PHIM','NĂM','TRẠNG THÁI','LƯỢT XEM','CẬP NHẬT','THAO TÁC'],items.map(m=>`<tr><td>${movieCell(m)}</td><td>${m.year}</td><td>${badge(m.status)}</td><td>${num(m.views)}</td><td class="muted">15/09/2026</td><td><div class="table-actions">${btn('Sửa','edit-movie','ghost sm','edit',`data-id="${m.id}"`)}${btn(m.status==='Ẩn'?'Công khai':'Ẩn','hide-movie','ghost sm','eye',`data-id="${m.id}"`)}${iconBtn('trash','Xoá '+m.title,'delete-movie',`data-id="${m.id}"`)}</div></td></tr>`).join(''),`<span>${items.length} / ${movies.length} phim · Bộ dữ liệu mẫu</span><span>Trang 1 / 1</span>`):empty('Không tìm thấy phim','Thử tên khác hoặc bỏ các bộ lọc đang áp dụng.','Bỏ lọc','clear-filter');}
function movieAdmin(){return `${pageTitle('Thư viện phim',`${movies.length} nội dung · Quản lý từ bản nháp đến công khai`,btn('Thêm phim','new-movie','primary','plus'))}<section class="panel">${filterbar()}<div id="table-results">${movieRows()}</div></section>`;}
function episodePage(){return `${pageTitle('Tập & Season','Quản lý cấu trúc series và nguồn phát của từng tập.',btn('Thêm tập','new-episode','primary','plus'))}<section class="panel"><div class="toolbar"><select aria-label="Chọn series" id="series-select"><option>Hành tinh lặng im</option></select><select aria-label="Chọn season"><option>Season 1 · 8 tập</option></select><div class="grow"></div><small>Kéo dòng hoặc dùng nút ↑ ↓ để sắp xếp</small></div>${tableWrap(['','TẬP','TÊN TẬP','NGUỒN PHÁT','TRẠNG THÁI','THAO TÁC'],episodes.map((e,i)=>`<tr class="drag-row" draggable="true" data-drag="episode" data-id="${e.id}"><td>${ic('grip')}</td><td>${String(i+1).padStart(2,'0')}</td><td>${esc(e.title)}</td><td>${e.source}</td><td>${badge(e.status)}</td><td><div class="flex">${btn('↑','move-up','ghost sm','',`data-id="${e.id}" data-kind="episode" aria-label="Đưa tập lên" ${i===0?'disabled':''}`)}${btn('↓','move-down','ghost sm','',`data-id="${e.id}" data-kind="episode" aria-label="Đưa tập xuống" ${i===episodes.length-1?'disabled':''}`)}${btn('Sửa nguồn','edit-episode','ghost sm','edit',`data-id="${e.id}"`)}</div></td></tr>`).join(''),'<span>Thứ tự thay đổi trong phiên prototype hiện tại</span>')}</section>`;}
let genres=['Viễn tưởng','Phim Việt','Hành động','Kinh dị','Anime'];
function genrePage(){return `${pageTitle('Thể loại','Một cấu trúc rõ ràng giúp người xem tìm phim nhanh hơn.',btn('Thêm thể loại','new-genre','primary','plus'))}<section class="panel">${tableWrap(['TÊN THỂ LOẠI','SLUG','SỐ PHIM','THAO TÁC'],genres.map((g,i)=>`<tr><td>${esc(g)}</td><td class="muted">${slug(g)}</td><td>${movies.filter(m=>m.genre===g).length}</td><td>${btn('Sửa tên','edit-genre','ghost sm','edit',`data-id="${i}"`)}</td></tr>`).join(''))}</section>`;}
function userRows(){const items=people.filter(p=>matches(p.name+' '+p.mail,p.status));return items.length?tableWrap(['NGƯỜI DÙNG','VAI TRÒ','TRẠNG THÁI','GẦN NHẤT','THAO TÁC'],items.map(p=>`<tr><td><div class="flex"><span class="avatar">${p.name.split(' ').map(x=>x[0]).slice(-2).join('')}</span><div><strong>${p.name}</strong><br><small>${p.mail}</small></div></div></td><td>${badge(p.role,p.role==='admin'?'gold':'')}</td><td>${badge(p.status)}</td><td>${p.date}</td><td><div class="flex">${btn('Chi tiết','user-detail','ghost sm','',`data-id="${p.id}"`)}${btn(p.status==='Đã khoá'?'Mở khoá':'Khoá','user-lock','ghost sm','lock',`data-id="${p.id}" ${p.role==='admin'?'disabled title="Không khoá quản trị viên trong prototype"':''}`)}</div></td></tr>`).join('')):empty('Không tìm thấy tài khoản','Thử tìm tên hoặc email khác.','Bỏ lọc','clear-filter');}
function usersPage(){return `${pageTitle('Người dùng','Quản lý quyền truy cập và theo dõi trải nghiệm xem.')}<section class="panel">${filterbar(['Tất cả','Hoạt động','Đã khoá'],'Tìm tên hoặc email…')}<div id="table-results">${userRows()}</div></section>`;}
function commentRows(){const items=comments.filter(c=>matches(c.name+' '+c.text+' '+c.movie,c.status));return items.length?tableWrap(['<input type="checkbox" id="select-all" aria-label="Chọn tất cả bình luận">','BÌNH LUẬN','PHIM','TRẠNG THÁI','THAO TÁC'],items.map(c=>`<tr><td><input type="checkbox" data-select="${c.id}" aria-label="Chọn bình luận của ${c.name}" ${S.selected.has(c.id)?'checked':''}></td><td style="white-space:normal;min-width:260px;max-width:430px"><strong>${c.name}</strong><p class="muted" style="margin-top:4px">${esc(c.text)}</p></td><td>${esc(c.movie)}</td><td>${badge(c.status)}</td><td>${btn('Duyệt','approve-comment','ghost sm','check',`data-id="${c.id}" ${c.status==='Đã duyệt'?'disabled':''}`)}</td></tr>`).join('')):empty('Không có bình luận','Không có bình luận phù hợp với bộ lọc hiện tại.','Bỏ lọc','clear-filter');}
function commentsPage(){return `${pageTitle('Kiểm duyệt bình luận','Duyệt nội dung mới, xử lý báo cáo và bảo vệ cộng đồng.')}<section class="panel">${filterbar(['Tất cả','Chờ duyệt','Đã duyệt','Bị báo cáo','Đã ẩn'],'Tìm nội dung hoặc người gửi…')}<div class="toolbar"><span class="muted" id="selected-count">${S.selected.size} đã chọn</span>${btn('Duyệt','bulk-approve','ghost sm','check')}${btn('Ẩn','bulk-hide','ghost sm','eye')}${btn('Xoá','bulk-delete','danger sm','trash')}</div><div id="table-results">${commentRows()}</div></section>`;}
function bannersPage(){return `${pageTitle('Banner / Hero','Sắp xếp điểm chạm đầu tiên của người xem.',btn('Thêm banner','new-banner','primary','plus'))}<div class="health-line">${ic('clock')}Lịch hiển thị dùng múi giờ Asia/Ho_Chi_Minh. Kéo thả hoặc dùng nút ↑ ↓ để đổi thứ tự.</div><div class="stack" style="margin-top:24px">${banners.map((b,i)=>`<section class="panel drag-row" draggable="true" data-drag="banner" data-id="${b.id}"><div class="panel-body"><div class="two-col"><div class="banner-preview"><img src="${findMovie(b.movieId).wide}" alt=""><strong>${findMovie(b.movieId).title}</strong></div><div><div class="flex between"><span class="eyebrow">VỊ TRÍ 0${i+1}</span>${badge('Đã lên lịch','gold')}</div><p class="muted" style="margin:12px 0;font-size:12px">${b.start.replace('T',' · ')} → ${b.end.replace('T',' · ')}</p><div class="flex">${btn('Chỉnh lịch','edit-banner','ghost sm','edit',`data-id="${b.id}"`)}${btn('↑','move-up','ghost sm','',`data-kind="banner" data-id="${b.id}" aria-label="Đưa banner lên" ${i===0?'disabled':''}`)}${btn('↓','move-down','ghost sm','',`data-kind="banner" data-id="${b.id}" aria-label="Đưa banner xuống" ${i===banners.length-1?'disabled':''}`)}</div></div></div></div></section>`).join('')}</div>`;}
let sources=[{id:1,name:'Nguồn chính · Việt Nam',type:'HLS',url:'https://media.example.test/vn/master.m3u8',status:'Sẵn sàng'},{id:2,name:'Nguồn dự phòng · Singapore',type:'HLS',url:'https://media.example.test/sg/master.m3u8',status:'Sẵn sàng'}];
function sourcesPage(){return `${pageTitle('Máy chủ phát','Gắn nguồn nội dung vào phim. Theo dõi hạ tầng chi tiết ở giao diện Server.',btn('Thêm nguồn','new-source','primary','plus'))}<section class="panel">${tableWrap(['TÊN NGUỒN','GIAO THỨC','ĐƯỜNG DẪN MẪU','TRẠNG THÁI',''],sources.map(s=>`<tr><td>${esc(s.name)}</td><td>${s.type}</td><td class="muted">${esc(s.url)}</td><td>${badge(s.status)}</td><td>${btn('Chỉnh sửa','edit-source','ghost sm','edit',`data-id="${s.id}"`)}</td></tr>`).join(''))}</section>`;}
function reportsPage(){return `${pageTitle('Báo cáo nội dung','Dữ liệu minh hoạ trong 7 ngày · 09–15/09/2026',btn('Tải CSV','export','primary','download'))}<div class="stack"><div class="kpis">${kpi('Tổng lượt xem','164.820','7 ngày gần nhất','eye','12,8%')}${kpi('Thời gian xem TB','42 phút','mỗi phiên','clock','4,6%')}${kpi('Xem hết phim','68,4%','trên phiên đủ điều kiện','check')}${kpi('Báo cáo chưa xử lý','12','nguồn phát gián đoạn','alert')}</div><section class="panel"><div class="panel-head"><h3>Hiệu quả từng phim</h3><span class="legend">Lượt xem</span></div>${tableWrap(['PHIM','LƯỢT XEM','THỜI GIAN XEM TB','HOÀN THÀNH',''],movies.filter(m=>m.views>0).map((m,i)=>`<tr><td>${movieCell(m)}</td><td>${num(m.views)}</td><td>${42-i*3} phút</td><td>${76-i*4}%</td><td>${btn('Chi tiết','report-detail','ghost sm','chevron',`data-id="${m.id}"`)}</td></tr>`).join(''))}</section></div>`;}
function overview(){const down=nodes.filter(n=>n.status==='Down').length;return `${pageTitle('Tổng quan cụm','Đông Nam Á · 4 edge nodes · Dữ liệu mô phỏng cập nhật mỗi 5 giây',badge('LIVE DEMO','green')+btn('Làm mới','refresh-data','ghost','refresh'))}<div class="stack"><div class="health-line ${down?'warn':''}">${ic(down?'alert':'check')}<span>${down?'1 node mất kết nối. Lưu lượng đã chuyển sang edge-sin-01.':'Tất cả node đã phản hồi. Cụm đang hoạt động bình thường.'}</span><div class="grow"></div>${btn('Xem routing','page','ghost sm','chevron','data-id="routing"')}</div><div class="kpis">${kpi('CPU trung bình','<span data-live="cpu">51</span><small> %</small>','ngưỡng cảnh báo 80%','cpu')}${kpi('RAM sử dụng','<span data-live="ram">38,4</span><small> / 64 GB</small>','60% tổng dung lượng','server')}${kpi('Băng thông','<span data-live="bandwidth">3,82</span><small> Gbps</small>','giới hạn 10 Gbps','activity')}${kpi('Stream đang chạy','<span data-live="streams">3.736</span>','trên 3 node nhận lưu lượng','play')}</div><div class="charts"><section class="panel"><div class="panel-head"><div><h3>Băng thông toàn cụm</h3><small>Mẫu dữ liệu lịch sử · 60 phút</small></div><span class="legend">Outbound</span></div><div class="panel-body">${chart('bandwidth')}</div></section><section class="panel"><div class="panel-head"><h3>Sức khoẻ dịch vụ</h3>${ic('shield')}</div><div class="panel-body"><div class="metric-line"><span>HTTP 4xx</span><strong>0,28%</strong></div><div class="metric-line"><span>HTTP 5xx</span><strong style="color:#F4F5F7">0,14%</strong></div><div class="divider"></div><div class="metric-line"><span>CDN hit ratio</span><strong class="positive">94,8%</strong></div><div class="progress"><span style="width:94.8%;background:var(--success)"></span></div><div class="metric-line"><span>Lưu trữ</span><strong>7,2 / 10 TB</strong></div><div class="progress"><span style="width:72%"></span></div><small>Ngưỡng cảnh báo lưu trữ: 85%</small></div></section></div><section class="panel"><div class="panel-head"><h3>Node đang hoạt động</h3>${btn('Quản lý node','page','ghost sm','chevron','data-id="nodes"')}</div>${nodeTable(false)}</section></div>`;}
function nodeTable(actions=true){return tableWrap(['NODE / REGION','HEALTH','LOAD','CONNECTION','UPTIME',...(actions?['THAO TÁC']:[])],nodes.map(n=>`<tr><td><div class="node-name">${n.name}</div><small>${n.region} · ${n.ip}</small></td><td>${badge(n.status)}</td><td><div class="flex"><div class="meter ${n.load>65?'amber':''}"><span style="width:${n.load}%"></span></div><span>${n.load}%</span></div></td><td>${num(n.connections)}</td><td class="muted">${n.uptime}</td>${actions?`<td><div class="flex">${btn(n.status==='Draining'?'Resume':'Drain','node-drain','ghost sm','',`data-id="${n.id}" ${['Down','Maintenance'].includes(n.status)?'disabled':''}`)}${btn('Restart','node-restart','ghost sm','refresh',`data-id="${n.id}"`)}${btn(n.status==='Maintenance'?'End maintenance':'Maintenance','node-maintenance','ghost sm','',`data-id="${n.id}"`)}</div></td>`:''}</tr>`).join(''));}
function nodesPage(){return `${pageTitle('Node / Server phát','Điều phối lưu lượng, bảo trì và phục hồi từng node.',btn('Làm mới','refresh-data','ghost','refresh'))}<div class="stack"><div class="health-line warn">${ic('shield')}Các thao tác Drain / Restart / Maintenance chỉ mô phỏng. Luôn có xác nhận và nêu ảnh hưởng trước khi thực hiện.</div><section class="panel">${nodeTable()}</section><div class="two-col"><section class="panel panel-body"><h3>Drain trước khi bảo trì</h3><p class="spec" style="margin-top:12px">Ngừng nhận phiên mới, để các phiên đang xem kết thúc. Sau đó mới chuyển node sang Maintenance.</p></section><section class="panel panel-body"><h3>Trạng thái rõ ràng, không chỉ bằng màu</h3><div class="flex wrap" style="margin-top:16px">${badge('Healthy')}${badge('Draining')}${badge('Down')}</div><p class="spec" style="margin-top:12px">Màu luôn đi kèm nhãn chữ; không dựa riêng vào màu để nhận biết sự cố.</p></section></div></div>`;}
function transcodePage(){return `${pageTitle('Nguồn phim & Transcode','Hàng đợi xử lý nội dung · 2 worker · Dữ liệu mô phỏng',btn('Thêm tác vụ','new-job','primary','plus'))}<div class="stack"><div class="kpis">${kpi('Đang encode',queue.filter(q=>q.status==='Đang encode').length,'worker-01','cpu')}${kpi('Đang chờ',queue.filter(q=>q.status==='Đang chờ').length,'xử lý theo FIFO','clock')}${kpi('Thất bại',queue.filter(q=>q.status==='Thất bại').length,'cần kiểm tra nguồn','alert')}${kpi('Đã hoàn thành','24','hôm nay · mẫu','check')}</div><section class="panel"><div class="panel-head"><h3>Hàng đợi encode</h3><small>H.264 / AAC · HLS</small></div>${queue.map(q=>`<div class="queue-item"><div class="flex between"><strong>${esc(q.title)}</strong>${badge(q.status)}</div><div class="progress"><span style="width:${q.p}%;background:${q.status==='Thất bại'?'var(--error)':'var(--accent)'}"></span></div><div class="flex between"><small>${q.status==='Thất bại'?'SOURCE_TIMEOUT · Nguồn không phản hồi':q.p+'% · '+(q.p?'Đang xuất 1080p · 4.500 kbps':'Đang chờ worker khả dụng')}</small>${q.status==='Thất bại'?btn('Retry','retry-job','ghost sm','refresh',`data-id="${q.id}"`):''}</div><div class="flex" style="margin-top:12px">${badge('360p · 800 kbps',q.p>20?'green':'')}${badge('720p · 2.500 kbps',q.p>50?'green':'')}${badge('1080p · 4.500 kbps',q.p===100?'green':'')}</div></div>`).join('')}</section></div>`;}
let rules=[{id:1,region:'Việt Nam',primary:'edge-sgn-01',backup:'edge-sin-01',threshold:80},{id:2,region:'Đông Nam Á',primary:'edge-sin-01',backup:'edge-han-01',threshold:75}];let failover=true;
function routingPage(){return `${pageTitle('Routing & Failover','Ưu tiên độ trễ thấp, giữ tải dưới ngưỡng và luôn có nguồn dự phòng.',btn('Thử node down','simulate-down','ghost','activity'))}<div class="stack"><section class="panel"><div class="panel-head"><h3>Luồng chuyển tuyến minh hoạ</h3>${badge(failover?'Failover active':'Primary active',failover?'amber':'green')}</div><div class="path"><div class="path-node">Người xem<small>Geo: Việt Nam</small></div>${ic('chevron')}<div class="path-node">Router<small>Geo → Load → Health</small></div>${ic('chevron')}<div class="path-node ${failover?'fail':'ok'}">edge-sgn-02<small>${failover?'DOWN · bỏ qua':'HEALTHY · nguồn chính'}</small></div>${ic('chevron')}<div class="path-node ok">edge-sin-01<small>${failover?'Nhận phiên thay thế':'Sẵn sàng dự phòng'}</small></div></div><p class="spec" style="padding:0 20px 20px">${failover?'Health check thất bại → loại node khỏi pool → chọn backup còn khoẻ. Player nhận nguồn thay thế để tiếp tục phát.':'Router đang chọn nguồn chính còn khoẻ. Nguồn backup được giữ sẵn để xử lý sự cố.'}</p></section><section class="panel"><div class="panel-head"><h3>Quy tắc chọn nguồn</h3>${btn('Thêm rule','new-rule','primary sm','plus')}</div>${tableWrap(['KHU VỰC','ƯU TIÊN','NGƯỠNG TẢI','BACKUP',''],rules.map(r=>`<tr><td>${esc(r.region)}</td><td>${r.primary}</td><td>${r.threshold}%</td><td>${r.backup}</td><td>${btn('Sửa','edit-rule','ghost sm','edit',`data-id="${r.id}"`)}</td></tr>`).join(''))}</section></div>`;}
const logs=[{id:1,time:'14:52:08',level:'Critical',node:'edge-sgn-02',message:'Health check thất bại 3 lần liên tiếp. Đã chuyển tuyến sang edge-sin-01.'},{id:2,time:'14:50:41',level:'Warning',node:'transcode-01',message:'SOURCE_TIMEOUT: Gió qua thành phố · Tập 03. Cần thử lại tác vụ.'},{id:3,time:'14:48:12',level:'Warning',node:'storage-02',message:'Dung lượng volume media-archive đạt 86%. Cần kiểm tra phân bổ.'},{id:4,time:'14:42:25',level:'Info',node:'router-01',message:'Đã tải cấu hình routing phiên bản 18.'},{id:5,time:'14:39:02',level:'Info',node:'edge-sin-01',message:'Health check thành công. Độ trễ 48 ms.'}];
function logRows(){const items=logs.filter(l=>matches(l.node+' '+l.message,l.level)&&(!S.logSince||l.time>=S.logSince));return items.length?tableWrap(['THỜI GIAN','MỨC ĐỘ','DỊCH VỤ','NỘI DUNG'],items.map(l=>`<tr><td class="muted">15/09 ${l.time}</td><td>${badge(l.level,l.level==='Critical'?'red':l.level==='Warning'?'amber':'')}</td><td>${l.node}</td><td style="white-space:normal;min-width:330px">${l.message}</td></tr>`).join('')):empty('Không có log phù hợp','Đổi mức độ hoặc mốc thời gian để xem thêm dữ liệu.','Bỏ lọc','clear-filter');}
function logsPage(){return `${pageTitle('Log & Cảnh báo','Tập trung các sự cố cần xử lý · Thời gian Asia/Ho_Chi_Minh',btn('Xuất log','export-logs','ghost','download'))}<section class="panel">${filterbar(['Tất cả','Critical','Warning','Info'],'Tìm node hoặc nội dung log…')}<div class="toolbar"><label class="flex muted" style="font-size:12px">Từ lúc <input id="log-since" aria-label="Lọc log từ thời điểm" type="time" value="${S.logSince||''}" style="width:135px"></label><small>15/09/2026 · dữ liệu mẫu</small></div><div id="table-results">${logRows()}</div></section>`;}
function storagePage(){return `${pageTitle('Lưu trữ & CDN','Theo dõi dung lượng, hiệu quả cache và áp lực lên origin.')}<div class="stack"><div class="kpis">${kpi('Dung lượng đã dùng','7,2 TB','trên 10 TB khả dụng','layers')}${kpi('CDN hit ratio','94,8%','ngưỡng kỳ vọng ≥ 90%','globe')}${kpi('Origin egress','198 GB','24 giờ gần nhất','activity')}${kpi('Cache TTL','24 giờ','nội dung media segments','clock')}</div><section class="panel"><div class="panel-head"><h3>Storage volumes</h3>${badge('1 cảnh báo','amber')}</div>${tableWrap(['VOLUME','SỬ DỤNG','DUNG LƯỢNG','HEALTH'],[['media-active',64,'3,2 / 5 TB'],['media-archive',86,'3,44 / 4 TB'],['transcode-temp',56,'0,56 / 1 TB']].map(([name,p,size])=>`<tr><td>${name}</td><td><div class="flex"><div class="meter ${p>85?'amber':''}"><span style="width:${p}%"></span></div>${p}%</div></td><td>${size}</td><td>${badge(p>85?'Cần giải phóng':'Bình thường',p>85?'amber':'green')}</td></tr>`).join(''))}</section></div>`;}
let settings={moderation:true,registration:true,notify:true,maintenance:false};
function settingsPage(){const ops=S.mode==='server';return `${pageTitle(ops?'Cài đặt vận hành':'Cài đặt workspace','Các thay đổi trong prototype chỉ lưu trong phiên hiện tại.')}<div class="two-col"><section class="panel"><div class="panel-head"><h3>${ops?'Chính sách hệ thống':'Nội dung & cộng đồng'}</h3></div><div class="panel-body">${(ops?[['notify','Thông báo sự cố','Gửi cảnh báo khi health chuyển sang lỗi.'],['maintenance','Chế độ bảo trì','Mô phỏng trạng thái bảo trì toàn cụm.']]:[['moderation','Duyệt bình luận mới','Bình luận chờ mod kiểm tra trước khi hiển thị.'],['registration','Cho phép đăng ký','Người xem có thể tạo tài khoản mới.']]).map(([k,t,d])=>`<div class="setting-row"><div><h3 style="font-size:13px">${t}</h3><p>${d}</p></div><button class="toggle ${settings[k]?'on':''}" role="switch" aria-checked="${settings[k]}" aria-label="${t}" data-action="toggle-setting" data-id="${k}"></button></div>`).join('')}<p class="spec" style="margin-top:18px">Bản triển khai thật cần kiểm tra quyền ở API và ghi nhật ký mọi thay đổi.</p></div></section><section class="panel"><div class="panel-head"><h3>Thông tin workspace</h3></div><form id="workspace-form"><div class="panel-body"><label class="field">Tên hiển thị<input name="name" required value="${esc(S.workspaceName||'VKU CINEMA Cinema')}"></label><label class="field" style="margin-top:18px">Múi giờ<select><option>Asia/Ho_Chi_Minh (UTC+7)</option></select></label><div style="margin-top:20px"><button class="btn primary" type="submit">Lưu cài đặt</button></div></div></form></section></div>`;}
function empty(title='Chưa có dữ liệu',desc='Nội dung sẽ xuất hiện ở đây sau khi được tạo.',label='Tạo nội dung đầu tiên',action='new-movie'){return `<div class="state-box"><div class="state-icon">${ic('layers')}</div><h2>${title}</h2><p>${desc}</p>${btn(label,action,'primary','plus')}</div>`;}
function stateView(state=S.state){if(state==='loading')return `<div class="stack" aria-busy="true" aria-label="Đang tải dữ liệu"><div class="skeleton" style="width:220px;height:32px"></div><div class="kpis">${Array.from({length:4},()=>'<div class="skeleton skeleton-card"></div>').join('')}</div><div class="skeleton" style="height:230px"></div>${Array.from({length:4},()=>'<div class="skeleton" style="height:44px"></div>').join('')}<p class="muted" style="font-size:12px">Đang tải dữ liệu…</p></div>`;if(state==='empty')return empty('Chưa có nội dung','Không có dữ liệu để hiển thị trong khu vực này.','Về trạng thái mặc định','reset-state');if(state==='error')return `<div class="state-box"><div class="state-icon" style="color:#F4F5F7">${ic('alert')}</div><h2>Chưa thể tải dữ liệu</h2><p>Kết nối đến dịch vụ bị gián đoạn. Dữ liệu hiện tại chưa bị thay đổi.</p>${btn('Thử lại','reset-state','primary','refresh')}<small>Mã mẫu: NETWORK_UNAVAILABLE</small></div>`;return `<div class="state-box"><div class="state-icon">${ic('lock')}</div><h2>Không có quyền truy cập</h2><p>Tài khoản hiện tại không được phép xem khu vực này. Liên hệ quản trị viên để được cấp quyền phù hợp.</p>${btn('Về trang tổng quan','reset-state','ghost','back')}<small>403 · Permission denied</small></div>`;}
function kitTokens(){return `${pageTitle('Một hệ thống. Ba trải nghiệm.','VKU CINEMA / Design system v2.0 · VKU palette · Đỏ / Vàng / Xanh',btn('Tải tokens JSON','export-tokens','primary','download'))}<div class="stack"><section class="panel"><div class="panel-head"><h3>01 — Color tokens</h3><small>Semantic colors · không hard-code trong component</small></div><div class="panel-body kit-grid">${Object.entries(tokens.colors).map(([k,v])=>`<div class="panel"><div class="swatch" style="background:${v}"></div><div class="swatch-caption">${k}<code>${v}</code></div></div>`).join('')}</div></section><div class="two-col"><section class="panel"><div class="panel-head"><h3>02 — Typography</h3><small>Inter / Segoe UI / sans-serif</small></div><div class="panel-body stack"><div><span class="eyebrow">DISPLAY · 72 · 600</span><p style="font-size:42px;letter-spacing:-1.5px">Cinema, considered.</p></div><div><small>H1 · 30 · 600</small><h1>Quản lý rõ ràng.</h1></div><div><small>H2 · 22 / 29 · 600</small><h2>Ít nhiễu. Đúng trọng tâm.</h2></div><p>Body · 14 / 22 — Nội dung dễ đọc trên nền tối.</p><small>Caption · 12 / 18 — Dữ liệu phụ, nhãn và thời gian.</small></div></section><section class="panel"><div class="panel-head"><h3>03 — Spacing & Layout</h3></div><div class="panel-body"><p class="spec">Grid <code>12 cột</code> · gutter <code>24px</code><br>Desktop ≥ 1200 · Tablet 768–1199 · Mobile &lt; 768<br>Sidebar 228px → rail 76px → drawer<br>Radius: control 10px · card 14px · modal 16px</p><div style="margin-top:20px">${[4,8,12,16,24,32,48,64].map(n=>`<div class="flex" style="margin:8px 0;font-size:11px"><span style="width:40px;color:var(--muted)">${n}px</span><span style="height:10px;width:${n*3}px;background:var(--accent);border-radius:2px"></span></div>`).join('')}</div></div></section></div></div>`;}
function kitComponents(){return `${pageTitle('Component library','Một nguồn thiết kế cho User, Admin và Operations.')}<div class="stack"><section class="panel"><div class="panel-head"><h3>Button / Icon button / Badge</h3></div><div class="panel-body stack"><div class="flex wrap">${btn('Primary action','demo-success','primary','plus')}${btn('Secondary','demo-success','ghost')}${btn('Destructive','demo-error','danger','trash')}${btn('Disabled','','','', 'disabled')}${iconBtn('settings','Cài đặt mẫu','demo-success')}</div><div class="flex wrap">${badge('Công khai')}${badge('Nháp')}${badge('Down')}${badge('Đã ẩn')}${badge('4K','gold')}</div><p class="spec">Control height ≥ 40px · bàn phím có focus ring 2px · action phá huỷ có xác nhận.</p></div></section><div class="two-col"><section class="panel"><div class="panel-head"><h3>Input / Select / Validation</h3></div><div class="panel-body stack"><label class="field">Tên phim<input placeholder="Nhập tên phim"></label><label class="field">Trạng thái<select><option>Công khai</option><option>Nháp</option></select></label><label class="field">SEO slug<input value="" placeholder="phia-sau-binh-minh" aria-invalid="true" aria-describedby="slug-error" style="border-color:var(--error)"><small id="slug-error" style="color:#F4F5F7">Vui lòng nhập đường dẫn hợp lệ.</small></label></div></section><section class="panel"><div class="panel-head"><h3>Modal / Toast / Poster</h3></div><div class="panel-body"><div class="flex wrap" style="margin-bottom:18px">${btn('Mở modal','new-movie','ghost','edit')}${btn('Toast thành công','demo-success','ghost')}${btn('Toast lỗi','demo-error','ghost')}</div><div class="flex">${poster(movies[0])}<p class="spec">Poster 2:3<br>Overlay trên hover / focus.<br>Trên mobile: chạm mở chi tiết.<br>Metadata không chồng lớp mặc định.</p></div></div></section></div></div>`;}
function kitStates(){return `${pageTitle('Các trạng thái không được bỏ quên','Loading, empty, error và permission denied dùng chung trên ba giao diện.')}<div class="two-col"><section class="panel"><div class="panel-head"><h3>Loading skeleton</h3></div><div class="panel-body">${stateView('loading')}</div></section><section class="panel"><div class="panel-head"><h3>Empty state</h3></div>${stateView('empty')}</section><section class="panel"><div class="panel-head"><h3>Error & Retry</h3></div>${stateView('error')}</section><section class="panel"><div class="panel-head"><h3>Permission denied</h3></div>${stateView('denied')}</section></div>`;}
function handoff(){return `${pageTitle('Bàn giao cho developer','Thiết kế có thể tách trực tiếp thành React components và Tailwind theme.')}<div class="stack"><section class="panel"><div class="panel-head"><h3>Component boundaries</h3></div><div class="panel-body spec"><code>AppShell</code> → UserShell / AdminShell / OperationsShell<br><code>Button · IconButton · Input · Select · Badge · Modal · Toast</code><br><code>MoviePoster · Hero · ContinueCard · PlayerControls</code><br><code>DataTable · FilterBar · KpiCard · HealthBadge · NodeActions</code><br><code>LoadingSkeleton · EmptyState · ErrorState · PermissionDenied</code></div></section><section class="panel"><div class="panel-head"><h3>Grid 12 cột · Gutter 24px</h3></div><div class="panel-body"><div style="display:grid;grid-template-columns:repeat(12,1fr);gap:24px">${Array.from({length:12},(_,i)=>`<div style="background:#161A22;height:70px;border-radius:4px;color:var(--accent);display:grid;place-items:center;font-size:11px">${i+1}</div>`).join('')}</div><p class="spec" style="margin-top:16px">KPI: 3 / 12 mỗi card. Chart: 8 / 12. Top films: 4 / 12. Tablet KPI: 6 / 12. Mobile: xếp theo thứ tự đọc; bảng cuộn trong container.</p></div></section><section class="panel"><div class="panel-head"><h3>Phạm vi prototype</h3></div><div class="panel-body spec">Tất cả phim, poster, nguồn phát, KPI, log và node đều là dữ liệu minh hoạ. Trạng thái tương tác lưu trong bộ nhớ, tải lại trang sẽ đặt lại. Không có login, upload server, video streaming, transcode hoặc lệnh vận hành thật.<br><br>Khi triển khai: xác thực và RBAC ở backend; API phân trang/tìm kiếm; telemetry thật qua SSE/WebSocket; player HLS/DASH; URL nguồn được kiểm soát; xác nhận và audit log cho hành động vận hành.</div></section></div>`;}
const tokens={colors:{background:'#0B0D12',backgroundAlt:'#12141A',surface:'#161A22',raised:'#202633',border:'#303846',text:'#F4F5F7',muted:'#A8B0BC',primary:'#E31C23',highlight:'#F5C518',brand:'#0057B8',onPrimary:'#FFFDFC',brandReadable:'#73B6FF'},spacing:[4,8,12,16,24,32,48,64],radius:{control:10,card:14,modal:16},grid:{columns:12,gutter:24},breakpoints:{mobile:0,tablet:768,desktop:1200},motion:{duration:240,easing:'cubic-bezier(.2,.7,.2,1)',reducedMotion:true},fontFamily:'Inter, Segoe UI, Arial, sans-serif',semantic:{focus:'highlight',cta:'primary',rating:'highlight',navigation:'brand',success:'brand',warning:'highlight',error:'primary'}};
function render(){const root=document.getElementById('root');let body;if(S.mode==='user'){body=userHeader()+`<main class="user-body">${S.state!=='ready'?`<div class="detail">${stateView()}</div>`:S.page==='detail'?detail():S.page==='player'?player():['catalog','mylist'].includes(S.page)?catalog():home()}</main><footer class="footer"><div>${logo()}<p style="margin-top:8px">Lấy cảm hứng từ sắc màu VKU · Thiết kế đồ án sinh viên.</p></div><span>Prototype giao diện · Phim và poster hư cấu<br>VKU CINEMA Design System / 2026</span></footer>`;}else{let routes=S.mode==='admin'?{dashboard,movies:movieAdmin,episodes:episodePage,genres:genrePage,users:usersPage,comments:commentsPage,banners:bannersPage,sources:sourcesPage,reports:reportsPage,settings:settingsPage}:S.mode==='server'?{overview,nodes:nodesPage,transcode:transcodePage,routing:routingPage,logs:logsPage,storage:storagePage,settings:settingsPage}:{tokens:kitTokens,components:kitComponents,states:kitStates,handoff};body=sidebar()+`<div class="ops-main">${topbar()}<main class="content">${S.state==='ready'?(routes[S.page]||Object.values(routes)[0])():stateView()}</main></div>`;}root.innerHTML=demoBar()+`<div class="app">${body}</div>`;document.title=`VKU CINEMA — ${S.mode==='user'?'Cinema':S.mode==='admin'?'Content Studio':S.mode==='server'?'Operations':'Design System'}`;}
function toast(message,error=false){let el=document.createElement('div');el.className='toast'+(error?' error':'');el.innerHTML=ic(error?'alert':'check')+`<span>${esc(message)}</span>`;document.getElementById('toasts').append(el);setTimeout(()=>el.remove(),4500);}
function openModal(title,content,footer='',formId=''){lastFocus=document.activeElement;document.getElementById('modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title" style="font-size:20px">${title}</h2>${iconBtn('close','Đóng hộp thoại','close-modal')}</div>${formId?`<form id="${formId}">`:''}<div class="modal-body">${content}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}${formId?'</form>':''}</section></div>`;document.body.style.overflow='hidden';document.querySelector('.modal input,.modal select,.modal textarea,.modal button')?.focus();}
function closeModal(){document.getElementById('modal-root').innerHTML='';document.body.style.overflow='';if(lastFocus?.isConnected)lastFocus.focus();}
const field=(label,name,value='',type='text',extra='')=>`<label class="field">${label}<input type="${type}" name="${name}" value="${esc(value)}" ${extra}></label>`;
const selectField=(label,name,opts,val)=>`<label class="field">${label}<select name="${name}">${opts.map(o=>`<option ${o===val?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`;
const saveFooter=()=>btn('Huỷ','close-modal','ghost','', 'type="button"')+'<button type="submit" class="btn primary">Lưu thay đổi</button>';
function slug(s){return s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');}
function movieForm(id){S.uploadedPoster=null;const m=id?findMovie(id):{id:0,title:'',year:2026,genre:'Viễn tưởng',duration:'120 phút',status:'Nháp'};S.editId=m.id;openModal(id?'Chỉnh sửa phim':'Thêm phim mới',`<div class="form-grid">${field('Tên phim *','title',m.title,'text','required maxlength="80"')}${field('Năm phát hành *','year',m.year,'number','required min="1900" max="2100"')}${selectField('Thể loại','genre',genres,m.genre)}${selectField('Trạng thái','status',['Nháp','Công khai','Ẩn'],m.status)}${field('Thời lượng','duration',m.duration)}${field('SEO slug *','slug',m.slug||slug(m.title),'text','required pattern="[a-z0-9]+(-[a-z0-9]+)*" title="Chữ thường không dấu, số và dấu gạch nối"')}<label class="field full">Mô tả<textarea name="description" placeholder="Tóm tắt nội dung phim…">${esc(m.description||'')}</textarea></label>${field('Trailer URL','trailer',m.trailer||'','url','placeholder="https://…"')}${selectField('Nguồn phát','source',sources.map(s=>s.name),m.source)}<label class="field full">Poster<div class="upload">${ic('upload')}<p>Chọn ảnh 2:3 · JPG / PNG / WEBP · tối đa 5 MB</p><input id="poster-upload" name="poster" type="file" accept="image/png,image/jpeg,image/webp" aria-label="Chọn poster"><div id="upload-preview"></div><small>Ảnh chỉ được xem trước trong phiên này.</small></div></label></div>`,saveFooter(),'movie-form');}
function confirmAction(title,text,action,id){openModal(title,`<p class="muted">${esc(text)}</p>`,btn('Huỷ','close-modal','ghost')+btn('Xác nhận',action,'danger','',`data-id="${id}"`));}
function updateTable(){const el=document.getElementById('table-results');if(el)el.innerHTML=({movies:movieRows,users:userRows,comments:commentRows,logs:logRows}[S.page]||movieRows)();}
function go(page){S.page=page;S.query='';S.filter='Tất cả';S.selected.clear();S.state='ready';S.isPlaying=false;render();window.scrollTo(0,0);}
function exportFile(name,text,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Đã tạo tệp '+name);}
function reorder(kind,id,direction,target){let list=kind==='episode'?episodes:banners;let from=list.findIndex(e=>e.id===id),to=target?list.findIndex(e=>e.id===target):from+direction;if(from<0||to<0||to>=list.length||from===to)return;list.splice(to,0,list.splice(from,1)[0]);render();toast('Đã cập nhật thứ tự trong bản mẫu.');}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el)return;event.preventDefault();let a=el.dataset.action,id=Number(el.dataset.id);if(a==='mode'){S.mode=el.dataset.id;go({user:'home',admin:'dashboard',server:'overview',kit:'tokens'}[S.mode]);return;}if(a==='page'){go(el.dataset.id);return;}if(a==='home'){if(S.mode!=='user'){S.mode='user';}go('home');return;}if(a==='reset-state'){S.state='ready';render();return;}if(a==='catalog'||a==='mylist'){S.genre='Tất cả';go(a);return;}if(a==='detail'){S.mode='user';S.movie=id||S.movie;go('detail');return;}if(a==='play'||a==='episode-play'){S.movie=id||S.movie;S.episode=a==='episode-play'?Number(el.dataset.episode):null;S.sourceError=false;S.mode='user';go('player');return;}if(a==='genre'){S.genre=el.dataset.id;const y=window.scrollY;render();window.scrollTo(0,y);return;}if(a==='list-toggle'){S.listed.has(id)?S.listed.delete(id):S.listed.add(id);const y=window.scrollY;render();window.scrollTo(0,y);toast(S.listed.has(id)?'Đã thêm phim vào danh sách.':'Đã bỏ phim khỏi danh sách.');return;}if(a==='toggle-play'){S.isPlaying=!S.isPlaying;render();return;}if(a==='mute'){S.muted=!S.muted;render();return;}if(a==='simulate-source'){S.sourceError=true;S.isPlaying=false;render();return;}if(a==='fallback'){S.sourceError=false;S.source='Singapore';S.isPlaying=true;render();toast('Đã chuyển sang nguồn Singapore (mô phỏng).');return;}if(a==='fullscreen'){document.getElementById('player-container')?.requestFullscreen?.().catch(()=>toast('Trình duyệt đang chặn chế độ toàn màn hình.',true));return;}if(a==='user-menu'){const open=document.getElementById('user-nav').classList.toggle('open');el.setAttribute('aria-expanded',String(open));return;}if(a==='sidebar-menu'){document.getElementById('sidebar').classList.toggle('mobile-open');return;}if(a==='close-modal'){closeModal();return;}if(a==='notifications'){openModal('Thông báo',`<div class="log-line">${badge('Nội dung','gold')}<div>Phía sau bình minh vừa được cập nhật.<br><small>Hôm nay · 14:30</small></div></div><div class="log-line">${badge('Hệ thống','amber')}<div>Node edge-sgn-02 mất kết nối, đã có nguồn dự phòng.<br><small>Hôm nay · 14:52 · dữ liệu mẫu</small></div></div>`,btn('Đã xem','close-modal','primary'));return;}if(a==='user-profile'){openModal('Tài khoản người xem','<div class="flex"><span class="avatar">MA</span><div><h3>Minh Anh</h3><p class="muted">minhanh@example.test</p></div></div><p class="spec" style="margin-top:20px">Tài khoản minh hoạ cho trải nghiệm User. Chuyển Admin / Server bằng thanh prototype phía trên.</p>',btn('Đóng','close-modal','primary'));return;}if(a==='new-movie'||a==='edit-movie'){movieForm(a==='edit-movie'?id:0);return;}if(a==='hide-movie'){let m=findMovie(id);m.status=m.status==='Ẩn'?'Công khai':'Ẩn';render();toast('Đã chuyển phim sang '+m.status.toLowerCase()+'.');return;}if(a==='delete-movie'){confirmAction('Xoá phim khỏi bản mẫu?',`“${findMovie(id).title}” sẽ bị xoá khỏi thư viện trong phiên hiện tại.`,'confirm-delete-movie',id);return;}if(a==='confirm-delete-movie'){movies.splice(movies.findIndex(m=>m.id===id),1);closeModal();render();toast('Đã xoá phim khỏi bản mẫu.');return;}if(a==='clear-filter'){S.query='';S.filter='Tất cả';S.logSince='';render();return;}if(a==='new-episode'||a==='edit-episode'){const e=episodes.find(e=>e.id===id)||{title:'',status:'Nháp'};S.editId=id;openModal('Cấu hình tập & nguồn phát',`<div class="form-grid">${field('Tên tập *','title',e.title,'text','required')}${selectField('Trạng thái','status',['Nháp','Công khai'],e.status)}${field('Nguồn Việt Nam (HLS)','primary',e.primary||'','url','placeholder="https://media.example.test/episode.m3u8"')}${field('Nguồn Singapore (backup)','backup',e.backup||'','url','placeholder="https://media.example.test/backup.m3u8"')}</div><p class="spec" style="margin-top:16px">Nguồn là URL mẫu. Prototype không gọi hoặc kiểm tra video từ URL.</p>`,saveFooter(),'episode-form');return;}if(a==='move-up'||a==='move-down'){reorder(el.dataset.kind,id,a==='move-up'?-1:1);return;}if(a==='new-genre'||a==='edit-genre'){S.editId=a==='new-genre'?-1:id;openModal('Thể loại',field('Tên thể loại *','name',a==='new-genre'?'':genres[id],'text','required maxlength="40"'),saveFooter(),'genre-form');return;}if(a==='user-lock'){let p=people.find(p=>p.id===id);confirmAction(p.status==='Đã khoá'?'Mở tài khoản?':'Khoá tài khoản?',`Thay đổi quyền truy cập của ${p.name} trong dữ liệu mẫu.`,'confirm-user-lock',id);return;}if(a==='confirm-user-lock'){let p=people.find(p=>p.id===id);p.status=p.status==='Đã khoá'?'Hoạt động':'Đã khoá';closeModal();render();toast('Đã cập nhật trạng thái tài khoản.');return;}if(a==='user-detail'){let p=people.find(p=>p.id===id);S.editId=id;openModal('Tài khoản · '+p.name,`<p class="muted" style="margin-bottom:20px">${p.mail}</p>${selectField('Vai trò','role',['user','mod','admin'],p.role)}<div class="divider"></div><h3>Lịch sử xem mẫu</h3>${movies.slice(0,3).map((m,i)=>`<div class="top-film"><img src="${m.poster}" alt=""><div><strong>${m.title}</strong><small>15/09/2026 · ${[42,26,58][i]} phút</small></div></div>`).join('')}`,saveFooter(),'user-form');return;}if(a==='approve-comment'){comments.find(c=>c.id===id).status='Đã duyệt';render();toast('Đã duyệt bình luận.');return;}if(a.startsWith('bulk-')){if(!S.selected.size){toast('Chọn ít nhất một bình luận trước.',true);return;}if(a==='bulk-delete'){confirmAction('Xoá bình luận đã chọn?',`${S.selected.size} bình luận sẽ bị xoá khỏi bản mẫu.`,'confirm-bulk-delete',0);return;}comments.filter(c=>S.selected.has(c.id)).forEach(c=>c.status=a==='bulk-approve'?'Đã duyệt':'Đã ẩn');S.selected.clear();render();toast('Đã cập nhật bình luận đã chọn.');return;}if(a==='confirm-bulk-delete'){comments=comments.filter(c=>!S.selected.has(c.id));S.selected.clear();closeModal();render();toast('Đã xoá các bình luận đã chọn.');return;}if(a==='new-banner'||a==='edit-banner'){S.editId=id;let b=banners.find(b=>b.id===id)||{movieId:1,start:'2026-09-16T08:00',end:'2026-09-23T23:59'};openModal('Lịch hiển thị banner',`<div class="form-grid">${selectField('Phim','movie',movies.map(m=>m.title),findMovie(b.movieId).title)}${field('Bắt đầu (giờ Việt Nam)','start',b.start,'datetime-local','required')}${field('Kết thúc (giờ Việt Nam)','end',b.end,'datetime-local','required')}</div>`,saveFooter(),'banner-form');return;}if(a==='new-source'||a==='edit-source'){S.editId=id;let s=sources.find(s=>s.id===id)||{};openModal('Nguồn phát nội dung',`<div class="form-grid">${field('Tên nguồn *','name',s.name||'','text','required')}${selectField('Giao thức','type',['HLS','DASH'],s.type)}<div class="field full">${field('URL nguồn *','url',s.url||'','url','required placeholder="https://media.example.test/master.m3u8"')}</div></div>`,saveFooter(),'source-form');return;}if(a==='report-detail'){let m=findMovie(id);openModal('Báo cáo · '+m.title,`${movieCell(m)}<div class="divider"></div><div class="two-col">${kpi('Lượt xem',num(m.views),'7 ngày · dữ liệu mẫu','eye')}${kpi('Báo cáo nguồn','12','chưa xử lý · mẫu','alert')}</div><p class="spec" style="margin-top:20px">Vấn đề phổ biến: gián đoạn nguồn chính. Kiểm tra tab Máy chủ phát và Operations → Log & Cảnh báo.</p>`,btn('Đóng','close-modal','primary'));return;}if(a==='export'){exportFile('vku-cinema-movie-report.csv','\uFEFFTên phim,Năm,Trạng thái,Lượt xem\n'+movies.map(m=>[m.title,m.year,m.status,m.views].map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\n'),'text/csv;charset=utf-8');return;}if(a==='export-logs'){exportFile('vku-cinema-logs.json',JSON.stringify(logs,null,2));return;}if(a==='export-tokens'){exportFile('vku-cinema-tokens.json',JSON.stringify(tokens,null,2));return;}if(a.startsWith('node-')){let n=nodes.find(n=>n.id===id);S.nodeAction=a;let text=a==='node-restart'?`Khởi động lại ${n.name} sẽ ngắt các phiên trên node. Trong prototype chỉ thay đổi trạng thái mô phỏng.`:a==='node-drain'?`Thay đổi chế độ nhận phiên mới của ${n.name}. Phiên đang xem sẽ được thoát dần trong hệ thống thật.`:`Đổi chế độ bảo trì của ${n.name}. Node bảo trì không nhận lưu lượng mới.`;confirmAction('Xác nhận thao tác vận hành',text,'confirm-node',id);return;}if(a==='confirm-node'){let n=nodes.find(n=>n.id===id);if(S.nodeAction==='node-restart'){n.status='Healthy';n.uptime='00d 00h';n.connections=0;n.load=8;}else if(S.nodeAction==='node-drain'){n.status=n.status==='Draining'?'Healthy':'Draining';}else{n.status=n.status==='Maintenance'?'Healthy':'Maintenance';n.connections=0;n.load=0;}closeModal();render();toast('Đã cập nhật '+n.name+' (mô phỏng).');return;}if(a==='refresh-data'){S.tick++;updateLive();toast('Đã cập nhật snapshot mẫu.');return;}if(a==='retry-job'){let q=queue.find(q=>q.id===id);q.status='Đang chờ';q.p=0;render();toast('Đã đưa tác vụ vào hàng đợi thử lại.');return;}if(a==='new-job'){openModal('Thêm tác vụ transcode',`<div class="form-grid">${field('Tên nội dung *','title','','text','required')}${field('Nguồn phim *','url','','url','required placeholder="https://media.example.test/source.mp4"')}</div><p class="spec" style="margin-top:16px">Preset: H.264 / AAC · 360p, 720p, 1080p. Chỉ thêm vào hàng đợi mẫu.</p>`,saveFooter(),'job-form');return;}if(a==='simulate-down'){failover=!failover;render();toast(failover?'Đã mô phỏng failover sang Singapore.':'Đã mô phỏng nguồn chính phục hồi.');return;}if(a==='new-rule'||a==='edit-rule'){S.editId=id;let r=rules.find(r=>r.id===id)||{region:'',threshold:80};openModal('Quy tắc routing',`<div class="form-grid">${field('Khu vực *','region',r.region,'text','required')}${field('Ngưỡng tải (%)','threshold',r.threshold,'number','min="1" max="95" required')}${selectField('Node ưu tiên','primary',nodes.map(n=>n.name),r.primary)}${selectField('Node backup','backup',nodes.map(n=>n.name),r.backup)}</div>`,saveFooter(),'rule-form');return;}if(a==='toggle-setting'){settings[el.dataset.id]=!settings[el.dataset.id];render();toast('Đã cập nhật cài đặt mẫu.');return;}if(a==='demo-success'){toast('Thay đổi đã được lưu thành công (mẫu).');return;}if(a==='demo-error'){toast('Không thể lưu. Vui lòng thử lại (mẫu).',true);return;}});
document.addEventListener('input',e=>{if(e.target.id==='table-query'){S.query=e.target.value;updateTable();}if(e.target.name==='title'&&e.target.closest('#movie-form')&&!S.editId){document.querySelector('#movie-form [name=slug]').value=slug(e.target.value);}if(e.target.id==='seek'){S.progress=Number(e.target.value);document.getElementById('play-time').textContent=Math.floor(S.progress*1.28)+':00 / 128:00';}if(e.target.id==='user-search'){let q=e.target.value.toLowerCase();document.getElementById('suggestions').innerHTML=q?`<div class="suggestions">${movies.filter(m=>m.status==='Công khai'&&(m.title+' '+m.genre).toLowerCase().includes(q)).map(m=>`<button data-action="detail" data-id="${m.id}"><img src="${m.poster}" alt=""><span>${m.title}<br><small>${m.year} · ${m.genre}</small></span></button>`).join('')||'<p class="muted" style="padding:12px">Không tìm thấy phim.</p>'}</div>`:'';}});
document.addEventListener('change',e=>{const id=e.target.id;if(id==='state-picker'){S.state=e.target.value;render();}if(id==='table-filter'){S.filter=e.target.value;updateTable();}if(id==='log-since'){S.logSince=e.target.value;updateTable();}if(e.target.dataset.select){e.target.checked?S.selected.add(Number(e.target.dataset.select)):S.selected.delete(Number(e.target.dataset.select));document.getElementById('selected-count').textContent=S.selected.size+' đã chọn';}if(id==='select-all'){comments.filter(c=>matches(c.name+' '+c.text+' '+c.movie,c.status)).forEach(c=>e.target.checked?S.selected.add(c.id):S.selected.delete(c.id));updateTable();document.getElementById('selected-count').textContent=S.selected.size+' đã chọn';}if(id.startsWith('player-')){const key={'player-source':'source','player-quality':'quality','player-subtitle':'subtitle','player-speed':'speed'}[id];if(key){S[key]=e.target.value;if(key==='source')S.sourceError=false;render();toast('Đã chọn '+e.target.value+' (mô phỏng).');}}if(id==='poster-upload'){const f=e.target.files[0];if(!f)return;if(f.size>5*1024*1024||!['image/jpeg','image/png','image/webp'].includes(f.type)){e.target.value='';toast('Chọn ảnh JPG, PNG hoặc WEBP dưới 5 MB.',true);return;}let reader=new FileReader();reader.onload=()=>{S.uploadedPoster=reader.result;document.getElementById('upload-preview').innerHTML=`<img src="${reader.result}" alt="Poster vừa chọn" style="height:110px;margin-top:12px;border-radius:6px">`;};reader.readAsDataURL(f);}});
document.addEventListener('submit',e=>{e.preventDefault();let f=new FormData(e.target),data=Object.fromEntries(f.entries()),id=e.target.id;if(id==='movie-form'){let m=movies.find(m=>m.id===S.editId);if(!m){m={id:Math.max(0,...movies.map(x=>x.id))+1,rating:'—',views:0,color:'#0057B8',theme:'city',sub:'NEW STORY',expires:'31/12/2026'};movies.push(m);}Object.assign(m,{title:data.title.trim(),year:Number(data.year),genre:data.genre,status:data.status,duration:data.duration,slug:data.slug,description:data.description,trailer:data.trailer,source:data.source});m.poster=S.uploadedPoster||art(m);m.wide=art(m,true);S.uploadedPoster=null;}else if(id==='episode-form'){let x=episodes.find(x=>x.id===S.editId);let d={title:data.title,status:data.status,primary:data.primary,backup:data.backup,source:[data.primary,data.backup].filter(Boolean).length+' nguồn'};if(x)Object.assign(x,d);else episodes.push({id:Math.max(0,...episodes.map(x=>x.id))+1,...d});}else if(id==='genre-form'){if(genres.includes(data.name)&&genres[S.editId]!==data.name){toast('Thể loại này đã tồn tại.',true);return;}if(S.editId<0)genres.push(data.name.trim());else{let old=genres[S.editId];genres[S.editId]=data.name.trim();movies.filter(m=>m.genre===old).forEach(m=>m.genre=data.name.trim());}}else if(id==='user-form'){if(S.editId===3&&data.role!=='admin'){toast('Giữ quyền admin cho tài khoản đang sử dụng trong bản mẫu.',true);return;}people.find(p=>p.id===S.editId).role=data.role;}else if(id==='banner-form'){if(data.end<=data.start){toast('Thời gian kết thúc phải sau thời gian bắt đầu.',true);return;}let d={movieId:movies.find(m=>m.title===data.movie).id,start:data.start,end:data.end},b=banners.find(b=>b.id===S.editId);if(b)Object.assign(b,d);else banners.push({id:Math.max(0,...banners.map(b=>b.id))+1,...d});}else if(id==='source-form'){let s=sources.find(s=>s.id===S.editId),d={name:data.name,type:data.type,url:data.url,status:'Sẵn sàng'};if(s)Object.assign(s,d);else sources.push({id:sources.length+1,...d});}else if(id==='job-form'){queue.push({id:Math.max(0,...queue.map(q=>q.id))+1,title:data.title,p:0,status:'Đang chờ'});}else if(id==='rule-form'){if(data.primary===data.backup){toast('Node backup phải khác node ưu tiên.',true);return;}let d={region:data.region,primary:data.primary,backup:data.backup,threshold:Number(data.threshold)},r=rules.find(r=>r.id===S.editId);if(r)Object.assign(r,d);else rules.push({id:rules.length+1,...d});}else if(id==='comment-form'){if(!data.comment.trim())return;S.userComments.unshift({movie:S.movie,name:'Anh',text:data.comment.trim(),pending:true});render();toast('Đã gửi bình luận mẫu, đang chờ duyệt.');return;}else if(id==='workspace-form'){S.workspaceName=data.name.trim();toast('Đã lưu tên workspace trong phiên mẫu.');return;}closeModal();render();toast('Đã lưu thay đổi trong bản mẫu.');});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();document.getElementById('suggestions')?.replaceChildren();document.getElementById('sidebar')?.classList.remove('mobile-open');}if(e.key==='Enter'&&e.target.id==='global-search'){const q=e.target.value.toLowerCase();const m=movies.find(m=>m.title.toLowerCase().includes(q));const p=people.find(p=>(p.name+' '+p.mail).toLowerCase().includes(q));const n=nodes.find(n=>n.name.includes(q));if(!q)return;if(m){S.mode='admin';go('movies');S.query=q;render();}else if(p){S.mode='admin';go('users');S.query=q;render();}else if(n){S.mode='server';go('nodes');toast('Tìm thấy '+n.name);}else toast('Không có kết quả phù hợp.',true);}if(e.key==='Tab'&&document.querySelector('.modal')){let items=[...document.querySelectorAll('.modal button:not([disabled]),.modal input,.modal select,.modal textarea,.modal [tabindex="0"]')];const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
document.addEventListener('dragstart',e=>{let r=e.target.closest('[data-drag]');if(r){dragId={kind:r.dataset.drag,id:Number(r.dataset.id)};r.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',String(dragId.id));}});document.addEventListener('dragover',e=>{if(e.target.closest('[data-drag]'))e.preventDefault();});document.addEventListener('drop',e=>{let r=e.target.closest('[data-drag]');if(r&&dragId&&r.dataset.drag===dragId.kind){e.preventDefault();reorder(dragId.kind,dragId.id,0,Number(r.dataset.id));dragId=null;}});document.addEventListener('dragend',()=>document.querySelectorAll('.dragging').forEach(el=>el.classList.remove('dragging')));
function updateLive(){const vals={cpu:51+(S.tick%5)-2,ram:(38.4+(S.tick%4)*.2).toFixed(1).replace('.',','),bandwidth:(3.82+(S.tick%5)*.03).toFixed(2).replace('.',','),streams:num(3736+(S.tick%6)*12)};Object.entries(vals).forEach(([k,v])=>document.querySelectorAll(`[data-live="${k}"]`).forEach(e=>e.textContent=v));}setInterval(()=>{S.tick++;if(S.mode==='server')updateLive();},5000);setInterval(()=>{if(S.page==='player'&&S.isPlaying&&!S.sourceError){S.progress=Math.min(100,S.progress+.15);let seek=document.getElementById('seek');if(seek)seek.value=S.progress;let t=document.getElementById('play-time');if(t)t.textContent=Math.floor(S.progress*1.28)+':00 / 128:00';if(S.progress>=100){S.isPlaying=false;render();}}},1000);
render();

